// Simulación 2: 1000 asignaciones por un bus al-menos-una-vez, con 12 % de reentregas
function prng(semilla) {
  let s = semilla;
  return () => { s = (s * 1664525 + 1013904223) >>> 0; return s / 4294967296; };
}
const azar = prng(2026);
const entregas = [];
for (let i = 0; i < 1000; i++) {
  const evento = { id: "asig-" + i, camion: i % 20 };
  entregas.push(evento);
  if (azar() < 0.12) entregas.push(evento); // el ack se perdió: el bus reenvía
}
const sinClave = {};
for (const e of entregas) sinClave[e.camion] = (sinClave[e.camion] || 0) + 1;
const vistos = new Set();
const conClave = {};
for (const e of entregas) {
  if (vistos.has(e.id)) continue;
  vistos.add(e.id);
  conClave[e.camion] = (conClave[e.camion] || 0) + 1;
}
const total = (o) => Object.values(o).reduce((a, b) => a + b, 0);
console.log("entregas del bus:", entregas.length);
console.log("sin clave, asignaciones aplicadas:", total(sinClave));
console.log("con clave, asignaciones aplicadas:", total(conClave));
console.log("camión 0 sin clave:", sinClave[0], "| con clave:", conClave[0], "(esperado 50)");
